class FenwickRange:
    """扩展树状数组: 区间加 + 区间求和。双 BIT 维护差分 d[i] 与 d[i]*i。"""
    def __init__(self, n, init=None):
        self.n = n
        self.b1 = [0] * (n + 1)
        self.b2 = [0] * (n + 1)
        if init:
            for i, v in enumerate(init, 1):
                self.range_add(i, i, v)

    def _add(self, bit, i, x):
        while i <= self.n:
            bit[i] += x
            i += i & -i

    def _sum(self, bit, i):
        s = 0
        while i > 0:
            s += bit[i]
            i -= i & -i
        return s

    def range_add(self, l, r, x):
        self._add(self.b1, l, x)
        self._add(self.b1, r + 1, -x)
        self._add(self.b2, l, x * (l - 1))
        self._add(self.b2, r + 1, -x * r)

    def prefix_sum(self, i):
        return self._sum(self.b1, i) * i - self._sum(self.b2, i)

    def range_sum(self, l, r):
        return self.prefix_sum(r) - self.prefix_sum(l - 1)


class FenwickDiff:
    """扩展树状数组: 区间加 + 单点查 (单 BIT 维护差分)"""
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, i, x):
        while i <= self.n:
            self.bit[i] += x
            i += i & -i

    def range_add(self, l, r, x):
        self.add(l, x)
        self.add(r + 1, -x)

    def point(self, i):
        s = 0
        while i > 0:
            s += self.bit[i]
            i -= i & -i
        return s


if __name__ == "__main__":
    import random
    a = [random.randint(-100, 100) for _ in range(20)]
    n = len(a)
    fr = FenwickRange(n, a)
    assert fr.range_sum(1, n) == sum(a)
    assert fr.range_sum(5, 10) == sum(a[4:10])
    fr.range_add(3, 7, 5)
    for i in range(3, 8):
        a[i - 1] += 5
    assert fr.range_sum(1, n) == sum(a)
    assert fr.range_sum(4, 6) == sum(a[3:6])
    fd = FenwickDiff(n)
    b = [0] * n
    for _ in range(100):
        l = random.randint(1, n)
        r = random.randint(l, n)
        x = random.randint(-10, 10)
        fd.range_add(l, r, x)
        for i in range(l - 1, r):
            b[i] += x
    for i in range(n):
        assert fd.point(i + 1) == b[i]
    print("fenwick-extended OK")
